        let k = create__mmask32_from(0x55555555u32);
        let masked = unpack__m256i_to_i8_array(_mm256_maskz_max_epi8(k, a, b));
        let plain = unpack__m256i_to_i8_array(_mm256_max_epi8(a, b));
